export function visualGeometry(b){const baseW=b.resizeMode!=='reflow'&&Number(b.renderWidth)>0?b.renderWidth:b.w,baseH=b.resizeMode!=='reflow'&&Number(b.renderHeight)>0?b.renderHeight:b.h,scale=Math.min(b.w/baseW,b.h/baseH);return {w:b.w/scale,h:b.h/scale,sx:scale,sy:scale};}
export function resizeVisualBlock(b,w,h){if(b.locked)return b;w=Math.max(25,Math.min(4000,Number(w)||b.w));h=Math.max(25,Math.min(4000,Number(h)||b.h));if(b.resizeMode!=='reflow'&&(w!==b.w||h!==b.h)){b.renderWidth??=b.w;b.renderHeight??=b.h;}b.w=w;b.h=h;return b;}
export function resetVisualGeometry(b){delete b.renderWidth;delete b.renderHeight;}
export function expandVisualHeight(b,height){const g=visualGeometry(b);if(b.renderHeight!==undefined)b.renderHeight=height/g.sy;b.h=height;return b;}
export function splitVisualContent(doc,id,split){const original=doc.blocks.find(b=>b.id===id);if(!original||original.renderWidth===undefined&&original.renderHeight===undefined)return split();const g=visualGeometry(original),index=doc.blocks.indexOf(original),base={...original,w:g.w,h:g.h,rotation:0};resetVisualGeometry(base);doc.blocks[index]=base;const ids=split();if(ids.length===1&&ids[0]===id){doc.blocks[index]=original;return ids;}const angle=(original.rotation||0)*Math.PI/180,cx=original.x+original.w/2,cy=original.y+original.h/2;for(const part of doc.blocks.filter(b=>ids.includes(b.id))){const w=part.w,h=part.h,x=original.x+(part.x-original.x)*g.sx,y=original.y+(part.y-original.y)*g.sy;part.w=Math.max(25,w*g.sx);part.h=Math.max(25,h*g.sy);part.renderWidth=w;part.renderHeight=h;part.x=x;part.y=y;part.visualStyle=structuredClone(original.visualStyle||{});if(angle){const dx=x+part.w/2-cx,dy=y+part.h/2-cy;part.x=cx+dx*Math.cos(angle)-dy*Math.sin(angle)-part.w/2;part.y=cy+dx*Math.sin(angle)+dy*Math.cos(angle)-part.h/2;part.rotation=original.rotation;}}return ids;}
